#include "ci_basic_error.h"
#include "ci_frontend_modname.h"
#include "ci_detection_modname.h"

#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_INPUT_DIR_EMPTY                    ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,100) //输入的路径为空
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_MODEL_EMPTY                        ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,101) //载入的模型为空
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_DEVICE_MISMATCH                    ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,102) //选择的推理模型类型（GPU/CPU）与本机设备不相符
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_ENGINE_ERROR                       ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,103) //输入的推理引擎类型错误
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_IMG_EMPTY                          ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,105) //输入的图像为空,或存储的结果为空
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_DL_THRESH_ERROR                    ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,106) //输入的DL检测阈值超出边界
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_MERGE_THRESH_ERROR                 ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,107) //输入的merge阈值超出边界
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_IMG_CAPTURE_PATH_ERROR             ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,108) //输入的图像索引类型错误,请检查调用DLCabinetDefectStitchImage接口时，输入的in_img_order信息是否正确
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_IMG_NUMS_ERROR                     ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,109) //输入的图像数量,请检查输入的图像像素重叠数或待合并的图像数量是否有误
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_IMG_SIZE_ERROR                     ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,110) //输入的拼接图像大小不一致
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_OVERLAP_NUMS_ERROR                 ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,111) //图像拼接重合区未输入域或错误，overlapnum不可小于0
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_DETECT_TYPE_ERROR                  ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,112) //检测缺陷类型错误，不在DLCabinetDefectDetectType范围内
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_MODEL_SIZE_ERROR                   ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,113) //输入的模型尺寸错误，检查输入模型
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_MODEL_INFER_ERROR                  ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,114) //模型推理错误，请检查模型是否只支持单张样本推理
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_OVERLAP_NUM_ERROR                  ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,115) //裁切图像时重叠参数错误
#define ALGOMOD_DL_CABINET_DEFECT_DETECTOR_DEFECT_SIZE_ERROR                  ERROR_CODE(ALGOMOD_DL_CABINET_DEFECT_DETECTOR,116) //期望检出缺陷尺寸错误


